/* ============================================
   STATUS DOT COMPONENT
   Bare presence/status indicator with optional
   label, hollow outline and live pulse
   ============================================ */

/* Base */

.ds-status-dot {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-100);
}

.ds-status-dot__indicator {
  position: relative;
  flex-shrink: 0;
  border-radius: var(--radius-pill);
  background-color: var(--ds-status-dot-color);
}

.ds-status-dot__label {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-secondary);
  white-space: nowrap;
}

/* Sizes — the dot rides the icon scale at half-diameter, so it can never
   drift from the glyphs it sits beside. `xs` is the one step off it: the
   list-row mark sits on the gap scale, because no icon token is that small
   and 8px matches a title's cap height. */

.ds-status-dot--xs .ds-status-dot__indicator {
  width: var(--gap-200); /* 8px */
  height: var(--gap-200);
}

.ds-status-dot--sm .ds-status-dot__indicator {
  width: calc(var(--icon-size-500) / 2); /* 10px */
  height: calc(var(--icon-size-500) / 2);
}

.ds-status-dot--md .ds-status-dot__indicator {
  width: calc(var(--icon-size-600) / 2); /* 12px */
  height: calc(var(--icon-size-600) / 2);
}

.ds-status-dot--lg .ds-status-dot__indicator {
  width: calc(var(--icon-size-800) / 2); /* 16px */
  height: calc(var(--icon-size-800) / 2);
}

/* Variants — the plain-surface icon steps, tuned to hold on bare
   containers where the status text tints wash out. */

.ds-status-dot--info {
  --ds-status-dot-color: var(--color-status-info-icon);
}

.ds-status-dot--positive {
  --ds-status-dot-color: var(--color-status-positive-icon);
}

.ds-status-dot--warning {
  --ds-status-dot-color: var(--color-status-warning-icon);
}

.ds-status-dot--error {
  --ds-status-dot-color: var(--color-status-error-icon);
}

.ds-status-dot--neutral {
  --ds-status-dot-color: var(--color-status-neutral-icon);
}

/* Outline — the hollow dot: the role's colour drawn as an inset ring, so
   the mark keeps its box and its seat while reading as "nothing here yet".
   The two small sizes take the hairline; the larger two the heavier step,
   so the ring keeps its proportion to the diameter. */

.ds-status-dot--outline .ds-status-dot__indicator {
  background-color: transparent;
  box-shadow: inset 0 0 0 var(--border-025) var(--ds-status-dot-color);
}

.ds-status-dot--outline.ds-status-dot--md .ds-status-dot__indicator,
.ds-status-dot--outline.ds-status-dot--lg .ds-status-dot__indicator {
  box-shadow: inset 0 0 0 var(--border-050) var(--ds-status-dot-color);
}

/* Pulse — a ring of the dot's own colour swelling out and fading, on the
   shimmer loop so every live indicator in the system breathes at one rate. */

.ds-status-dot--pulse .ds-status-dot__indicator::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: var(--radius-pill);
  background-color: var(--ds-status-dot-color);
  animation: ds-status-dot-pulse var(--motion-duration-loop-shimmer) var(--motion-ease-standard)
    infinite;
}

@keyframes ds-status-dot-pulse {
  0% {
    transform: scale(1);
    opacity: 0.6;
  }
  70%,
  100% {
    transform: scale(2.2);
    opacity: 0;
  }
}

/* The looping ring parks rather than strobing through the collapsed
   duration — same treatment as the other looping indicators. */
@media (prefers-reduced-motion: reduce) {
  .ds-status-dot--pulse .ds-status-dot__indicator::after {
    animation: none;
    opacity: 0;
  }
}

import React from 'react';
import './StatusDot.css';

/** Props owned by StatusDot itself — everything else falls through to the root span. */
type StatusDotOwnProps = {
  /** Status role the dot carries — coloured through the plain-surface `--color-status-*-icon` steps. */
  variant?: 'info' | 'positive' | 'warning' | 'error' | 'neutral';
  /** Dot diameter, derived from the icon scale (half of `--icon-size-500/600/800`); `xs` is the 8px list-row mark, sized on the gap scale. */
  size?: 'xs' | 'sm' | 'md' | 'lg';
  /**
   * Draws the dot hollow: a ring in the role's colour around an empty
   * centre, for a settled or empty state that still holds its seat beside
   * filled dots.
   */
  outline?: boolean;
  /**
   * Radiates a repeating ring from the dot for a live state — recording,
   * online now, deploy in flight. The ring stills under reduced motion.
   */
  pulse?: boolean;
  /**
   * Visible text beside the dot. Omit it for a bare dot only when the meaning
   * has another home — a row label, or an `aria-label` passed through — since
   * a colour alone announces nothing.
   */
  label?: string;
  /**
   * Renders the dot as decoration: no `role="status"`, hidden from assistive
   * technology. For a dot repeated down a list, where the host announces the
   * state in the row's own text and a live region per row would be noise.
   */
  decorative?: boolean;
  /** Additional CSS classes */
  className?: string;
};

export interface StatusDotProps
  extends StatusDotOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof StatusDotOwnProps> {}

/**
 * StatusDot — the bare presence/status indicator: a small dot in one of the
 * five status roles, filled or hollow, with an optional visible label and
 * an optional live pulse. Where Badge carries a text label on a tinted fill, StatusDot is the
 * mark alone — for table rows, avatars, nav items, and anywhere a full badge
 * is too loud.
 *
 * Purely presentational: safe to render from a Server Component.
 */
export const StatusDot = React.forwardRef<HTMLSpanElement, StatusDotProps>(
  (
    {
      variant = 'neutral',
      size = 'md',
      outline = false,
      pulse = false,
      label,
      decorative = false,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-status-dot';

    const classes = [
      baseClass,
      `${baseClass}--${variant}`,
      `${baseClass}--${size}`,
      outline && `${baseClass}--outline`,
      pulse && `${baseClass}--pulse`,
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <span
        {...rest}
        ref={ref}
        className={classes}
        role={decorative ? undefined : 'status'}
        aria-hidden={decorative ? true : rest['aria-hidden']}
      >
        <span className={`${baseClass}__indicator`} aria-hidden="true" />
        {label && <span className={`${baseClass}__label`}>{label}</span>}
      </span>
    );
  },
);

StatusDot.displayName = 'StatusDot';
